// Postgres types that Drizzle doesn't know about, used by the generated schema.
import { customType } from 'drizzle-orm/pg-core';

/** Case-insensitive text (citext). Slugs and emails. */
export const citext = customType<{ data: string }>({
  dataType: () => 'citext',
});

/** A PostGIS point. Read and written as WKT/EWKT text by the app when needed. */
export const geography = customType<{ data: string }>({
  dataType: () => 'geography(point, 4326)',
});

/** The full-text search document. Generated by the database; never written by the app. */
export const tsvector = customType<{ data: string }>({
  dataType: () => 'tsvector',
});
